DO $provider_v7$
DECLARE ctl jsonb;q record;v record;h record;nb jsonb;before_state jsonb;after_state jsonb;used bigint;available bigint;rv bigint;
BEGIN
IF NOT pg_try_advisory_xact_lock(2026083000261022) THEN RAISE EXCEPTION 'PROVIDER_V7_QUIET_LOCK_BUSY';END IF;
IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE status='LEASED') OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_attempt WHERE outcome='RUNNING') OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease WHERE released_at IS NULL) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.connector_probe_lease_v1 WHERE released_at IS NULL) THEN RAISE EXCEPTION 'PROVIDER_V7_QUIET_WORK_REQUIRED';END IF;
ctl:=population_top3000_202608_202609_v1.continuation_guard_v6('top3000-completion-20261024-root-5db48b32d103',3,1);
SELECT * INTO STRICT q FROM population_top3000_202608_202609_v1.continuation_clear_queue_v6 WHERE clearing_id='resource:59488248e2bec1f0be084ef59e23a22380e599c60d174ba66d9c2ab194f2889d' FOR UPDATE;
IF q.claim_expires_at IS NULL OR q.not_after IS NULL OR q.input_sha256 IS DISTINCT FROM '59488248e2bec1f0be084ef59e23a22380e599c60d174ba66d9c2ab194f2889d' OR q.claim_token_sha256 IS DISTINCT FROM 'c5bd1276c42692936976c380eb567ccc39fb5c6d65aa768de75f2e9608a4caf3' OR q.status IS DISTINCT FROM 'CLAIMED' OR q.assignment_event_id<>50047 OR q.claim_expires_at<=clock_timestamp() OR q.not_after<=clock_timestamp() OR q.owner_id IS DISTINCT FROM ctl->>'owner_id' OR q.owner_fence<>3 OR q.stop_generation<>1 OR q.scope_sha256 IS DISTINCT FROM ctl->>'scope_sha256' OR q.assigned_executor IS DISTINCT FROM 'automation:6adc2c96db348191bca7cf4eacfdac32' OR NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=50055 AND event='ENGINEERING_CLEARING_CLAIMED_V6' AND details->>'clearing_id'=q.clearing_id) THEN RAISE EXCEPTION 'PROVIDER_V7_EXACT_CURRENT_CLAIM';END IF;
SELECT * INTO STRICT v FROM population_top3000_202608_202609_v1.resource_probe_v3 WHERE probe_id='f4cf7b1f-7012-4a3b-9a8e-b9a843a94205';
IF v.result->>'observed_at' IS NULL OR v.state IS DISTINCT FROM 'SUCCEEDED' OR v.owner_id IS DISTINCT FROM ctl->>'owner_id' OR v.owner_fence<>3 OR v.stop_generation<>1 OR v.scope_sha256 IS DISTINCT FROM ctl->>'scope_sha256' OR v.result_sha256 IS DISTINCT FROM '3073c7ccdce5365216e9b7185c8df30f2d8e9b32f165d2dc4ec0646899d502da' OR v.result_sha256 IS DISTINCT FROM encode(sha256(convert_to(v.result::text,'UTF8')),'hex') OR (v.result->>'observed_at')::timestamptz<clock_timestamp()-interval '10 minutes' OR (v.result->>'observed_at')::timestamptz>clock_timestamp() THEN RAISE EXCEPTION 'PROVIDER_V7_FRESH_PROBE';END IF;
IF current_setting('data_directory') NOT LIKE '/data/%' OR (SELECT count(*) FROM jsonb_array_elements(v.result->'metrics')m WHERE m->>'mountpoint'='/data')<>1 THEN RAISE EXCEPTION 'PROVIDER_V7_DATA_MOUNT';END IF;
SELECT (m->>'available_bytes')::bigint INTO available FROM jsonb_array_elements(v.result->'metrics')m WHERE m->>'mountpoint'='/data';
SELECT sum(pg_total_relation_size(oid)) INTO used FROM pg_class WHERE relnamespace='population_top3000_202608_202609_v1'::regnamespace AND relkind IN('r','m');
IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.acquisition_control a CROSS JOIN population_top3000_202608_202609_v1.pipeline_control p WHERE a.singleton AND p.singleton AND a.max_provider_requests=11000 AND a.provider_requests>=9680 AND a.provider_requests<11000 AND a.max_http_invocations=11055 AND a.http_invocations<11055 AND a.max_source_bytes=1500000000 AND p.max_ticks=30000 AND p.deadline='2026-10-25T22:36:17.687194Z' AND p.budget_evidence#>>'{resource_limits,max_relation_bytes}'='12000000000' AND p.budget_evidence#>>'{resource_limits,max_source_bytes}'='1500000000' AND p.budget_evidence#>>'{resource_limits,provider_request_ceiling}'='11000' AND p.budget_evidence#>>'{resource_limits,http_invocation_ceiling}'='11055' AND available-greatest(12000000000-used,0)-greatest(1500000000-a.stored_bytes-a.reserved_bytes,0)-a.reserved_bytes>=20000000000) THEN RAISE EXCEPTION 'PROVIDER_V7_EXACT_PREIMAGE_OR_HEADROOM';END IF;
IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='population_top3000_202608_202609_v1.acquisition_control'::regclass AND conname='acquisition_control_max_provider_requests_check') IS DISTINCT FROM 'CHECK (((max_provider_requests >= 0) AND (max_provider_requests <= 11000)))' OR (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='population_top3000_202608_202609_v1.acquisition_control'::regclass AND conname='acquisition_control_max_http_invocations_check') IS DISTINCT FROM 'CHECK (((max_http_invocations >= 0) AND (max_http_invocations <= 12000)))' THEN RAISE EXCEPTION 'PROVIDER_V7_CONSTRAINT_PREIMAGE';END IF;
IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE status='LEASED') OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease WHERE released_at IS NULL) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.connector_probe_lease_v1 WHERE released_at IS NULL) THEN RAISE EXCEPTION 'PROVIDER_V7_ACTIVE_WORK_RETRY_LATER';END IF;
SELECT * INTO STRICT h FROM population_top3000_202608_202609_v1.continuation_handler_v6 WHERE kind='CTX02_PAGE_ADMISSION' FOR UPDATE;
IF h.function_sha256 IS DISTINCT FROM '7b68f7313f94151d9c8a5590c2b80a5fd74a6c784e5c9a5f4b6c19ceee38252e' OR h.function_sha256 IS DISTINCT FROM encode(sha256(convert_to(pg_get_functiondef(h.function_oid),'UTF8')),'hex') OR encode(sha256(convert_to(h.bounds::text,'UTF8')),'hex') IS DISTINCT FROM '28a89b1d14b2621f20977926e0626d82c2a94f0513843b9561a26ee7e962d3cd' OR h.enabled IS DISTINCT FROM true OR h.review_event_id<>42667 THEN RAISE EXCEPTION 'PROVIDER_V7_POLICY_PREIMAGE';END IF;
nb:=jsonb_set(jsonb_set(h.bounds,'{global_ceiling,provider_requests}','11900'),'{global_ceiling,http_invocations}','11955');
SELECT event_id INTO rv FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='RESOURCE_PROVIDER_V7_INDEPENDENT_REVIEW' AND details->>'approved'='true' AND details->>'rollback_execution_approved'='true' AND details->>'claim_event_id'='50055' AND details->>'clearing_id'=q.clearing_id AND details->>'probe_result_sha256'=v.result_sha256 AND details->>'handler_function_sha256'=h.function_sha256 AND details->>'handler_bounds_sha256'=encode(sha256(convert_to(nb::text,'UTF8')),'hex') AND details->>'owner_id'=ctl->>'owner_id' AND details->>'owner_fence'='3' AND details->>'stop_generation'='1' AND details->>'scope_sha256'=ctl->>'scope_sha256' AND nullif(details->>'producer','') IS NOT NULL AND nullif(details->>'reviewer','') IS NOT NULL AND details->>'producer' IS DISTINCT FROM details->>'reviewer' ORDER BY event_id DESC LIMIT 1;
IF rv IS NULL THEN RAISE EXCEPTION 'PROVIDER_V7_EXACT_INDEPENDENT_REVIEW';END IF;
SELECT (to_jsonb(a)-ARRAY['max_provider_requests','max_http_invocations'])||jsonb_build_object('pipeline',to_jsonb(p)-'budget_evidence','budget',p.budget_evidence#-'{resource_limits,provider_request_ceiling}'#-'{resource_limits,http_invocation_ceiling}','handler',to_jsonb(h)-ARRAY['bounds','review_event_id']) INTO before_state FROM population_top3000_202608_202609_v1.acquisition_control a CROSS JOIN population_top3000_202608_202609_v1.pipeline_control p WHERE a.singleton AND p.singleton;
ALTER TABLE population_top3000_202608_202609_v1.acquisition_control DROP CONSTRAINT acquisition_control_max_provider_requests_check;
ALTER TABLE population_top3000_202608_202609_v1.acquisition_control ADD CONSTRAINT acquisition_control_max_provider_requests_check CHECK(max_provider_requests>=0 AND max_provider_requests<=11900);
UPDATE population_top3000_202608_202609_v1.acquisition_control SET max_provider_requests=11900,max_http_invocations=11955 WHERE singleton;
UPDATE population_top3000_202608_202609_v1.pipeline_control SET budget_evidence=jsonb_set(jsonb_set(budget_evidence,'{resource_limits,provider_request_ceiling}','11900'),'{resource_limits,http_invocation_ceiling}','11955') WHERE singleton;
UPDATE population_top3000_202608_202609_v1.continuation_handler_v6 SET bounds=nb,review_event_id=rv WHERE kind='CTX02_PAGE_ADMISSION';
SELECT (to_jsonb(a)-ARRAY['max_provider_requests','max_http_invocations'])||jsonb_build_object('pipeline',to_jsonb(p)-'budget_evidence','budget',p.budget_evidence#-'{resource_limits,provider_request_ceiling}'#-'{resource_limits,http_invocation_ceiling}','handler',to_jsonb(hh)-ARRAY['bounds','review_event_id']) INTO after_state FROM population_top3000_202608_202609_v1.acquisition_control a CROSS JOIN population_top3000_202608_202609_v1.pipeline_control p CROSS JOIN population_top3000_202608_202609_v1.continuation_handler_v6 hh WHERE a.singleton AND p.singleton AND hh.kind='CTX02_PAGE_ADMISSION';
IF before_state IS DISTINCT FROM after_state THEN RAISE EXCEPTION 'PROVIDER_V7_COUNTER_HISTORY_CODE_OR_OTHER_BOUND_CHANGED';END IF;
INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('CONTINUATION_MEASURED_ADMISSION_V6',ctl||jsonb_build_object('admission_class','PROVIDER_HTTP_ONLY_FINITE_MEASURED_V7','clearing_id',q.clearing_id,'claim_event_id',50055,'probe_id',v.probe_id,'probe_result_sha256',v.result_sha256,'available_bytes',available,'mission_relation_bytes',used,'old_provider_limit',11000,'new_provider_limit',11900,'old_http_limit',11055,'new_http_limit',11955,'source_limit_unchanged',1500000000,'relation_limit_unchanged',12000000000,'tick_limit_unchanged',30000,'handler_bounds_sha256',encode(sha256(convert_to(nb::text,'UTF8')),'hex'),'independent_review_event_id',rv,'effects_known',true,'cumulative_counters_preserved',true,'original_deadline_preserved',true,'source_holds_unchanged',true,'no_source_acquisition',true,'code_manifest_unchanged',true,'successor_task_id','da79b746-8550-41c9-a6f0-3d87f4e352fd','family_accepted',false));
END $provider_v7$;
